#!/usr/bin/env python3
"""Parity test: a hand-ported C++ forward pass generated by
scripts/export_residual_weights.py (e.g. include/ommpc_ros2/
residual_model_ecrl.h or residual_model_ambient.h) must agree with the
original PyTorch model to numerical precision, or the two have drifted and
the C++ port should not be trusted to fly. Input width is inferred from the
fixture's own x_* columns, so this works for any adapter (16-D ecrl, 8-D
ambient, ...) -- pass --model_path pointing at the matching *_model_
normalized.pt.

Usage:
    build/ommpc_ros2/gen_residual_mlp_fixture run once to produce
    test/fixtures/residual_mlp_fixture.csv, then:

        conda run -n ecrl python3 test/test_residual_mlp_parity.py \\
            test/fixtures/residual_mlp_fixture.csv

This is intentionally NOT wired into ament/colcon's test runner, for the same
reason as test/test_residuals_parity.py: it depends on the `ecrl` conda
environment (numpy/pandas/torch), not the ROS python.
"""
import argparse
import os
import sys

import numpy as np
import pandas as pd
import torch

TOL = 2e-4  # float32-trained tanh MLP arithmetic, not exact double-precision linear algebra
# NOTE: ecrl_model.pt is the *plain* network -- it expects already-normalized
# input and returns normalized output (that's what it was trained on); the
# "_normalized" variant wraps it with the exact input-normalize /
# output-denormalize steps ecrlForward() replicates by hand, so that's the
# correct comparison target for raw physical-unit input, not the plain model.
DEFAULT_MODEL_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "models",
                                   "ecrl_model_normalized.pt")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("fixture_csv")
    parser.add_argument("--model_path", default=DEFAULT_MODEL_PATH,
                         help="Normalized (self-normalizing) TorchScript model matching whatever "
                              "was baked into residual_model_ecrl.h when the fixture was generated")
    args = parser.parse_args()

    df = pd.read_csv(args.fixture_csv)
    n = len(df)
    assert n > 0, "empty fixture"

    n_x = sum(1 for c in df.columns if c.startswith("x_"))
    n_y = sum(1 for c in df.columns if c.startswith("y_"))
    x_cols = [f"x_{i}" for i in range(n_x)]
    y_cols = [f"y_{i}" for i in range(n_y)]
    X = df[x_cols].values.astype(np.float32)
    Y_cpp = df[y_cols].values.astype(np.float64)

    model = torch.jit.load(args.model_path)
    model.eval()
    with torch.no_grad():
        Y_py = model(torch.tensor(X, dtype=torch.float32)).numpy().astype(np.float64)

    err = np.abs(Y_cpp - Y_py)
    max_err = err.max()
    max_err_row, max_err_col = np.unravel_index(np.argmax(err), err.shape)
    mean_err = err.mean()

    print(f"rows checked:     {n}")
    print(f"mean abs error:   {mean_err:.3e}")
    print(f"max abs error:    {max_err:.3e} (row {max_err_row}, output dim {max_err_col})")

    ok = max_err < TOL
    if not ok:
        print(f"FAIL: exceeds tolerance {TOL:.1e}", file=sys.stderr)
        sys.exit(1)
    print(f"PASS: all errors below {TOL:.1e}")


if __name__ == "__main__":
    main()
